import * as THREE from 'three/webgpu';
import { MeshStandardNodeMaterial } from 'three/tsl';
import { gsap } from 'gsap';
import { Object3D, Mesh, PlaneGeometry } from 'three';

/**
 * @typedef {Object} NodeConfig
 * @property {{imageUrl:string, depthMapUrl:string}} assets
 * @property {number[]} position
 * @property {number[]} rotation
 * @property {number[]} scale
 * @property {{name:string,params:any}[]} cinematicPrimitives
 */

/**
 * @typedef {Object} NodeContext
 * @property {(url:string)=>THREE.Texture} textureLoader
 * @property {{[key:string]:(obj:THREE.Object3D,params:any)=>void}} primitives
 * @property {(event:string)=>void} [emit]
 */

/**
 * Creates a parallax‑scroll stat tile.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // ----- Geometry ------------------------------------------------------------
  const geometry = new PlaneGeometry(1, 1, 64, 64);

  // ----- Textures ------------------------------------------------------------
  const colorTex = ctx.textureLoader(config.assets.imageUrl);
  const depthTex = ctx.textureLoader(config.assets.depthMapUrl);

  // ----- Material (TSL) ------------------------------------------------------
  const material = new MeshStandardNodeMaterial({
    map: colorTex,
    displacementMap: depthTex,
    displacementScale: 0.08,
    metalness: 0.0,
    roughness: 0.7,
    clearcoat: 0.2,
    clearcoatRoughness: 0.4,
    color: 0xffffff,
  });

  // ----- Mesh ---------------------------------------------------------------
  const plane = new Mesh(geometry, material);
  plane.position.set(...config.position);
  plane.rotation.set(...config.rotation);
  plane.scale.set(...config.scale);
  plane.matrixAutoUpdate = true;

  // ----- Interaction Handlers ------------------------------------------------
  let hoverTween = null;
  const originalY = plane.position.y;

  function onHover() {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.to(plane.position, {
      y: originalY + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
  }

  function onHoverOut() {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.to(plane.position, {
      y: originalY,
      duration: 0.7,
      ease: 'power3.out',
    });
  }

  function onClick() {
    // emit navigation event
    if (ctx.emit) ctx.emit('hub-features.select');

    // press‑down visual feedback
    gsap.to(plane.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out(1.7)',
      onComplete: () => {
        gsap.to(plane.scale, {
          x: 1,
          y: 1,
          z: 1,
          duration: 0.12,
          ease: 'back.out(1.7)',
        });
      },
    });
  }

  plane.userData.handlers = {
    pointerover: onHover,
    pointerout: onHoverOut,
    click: onClick,
  };

  // ----- Cinematic Primitives ------------------------------------------------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (typeof fn === 'function') {
        fn(plane, prim.params);
      }
    }
  }

  // ----- Cleanup -------------------------------------------------------------
  plane.userData.cleanup = () => {
    if (hoverTween) hoverTween.kill();
    geometry.dispose();
    if (material.map) material.map.dispose();
    if (material.displacementMap) material.displacementMap.dispose();
    material.dispose();
  };

  return plane;
}
